<?php require __DIR__.'/config/db.php';require __DIR__.'/includes/auth.php';require_role(['student']);$u=$_SESSION['user'];$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['office_id']??0);$q=$pdo->prepare('SELECT id FROM offices WHERE id=?');$q->execute([$id]);if($q->fetch()){$q=$pdo->prepare("INSERT INTO clearance_requests(student_id,office_id,status,student_note) VALUES(?,?,'Pending',?) ON DUPLICATE KEY UPDATE student_note=VALUES(student_note),status=IF(status='Cleared','Cleared','Pending'),updated_at=CURRENT_TIMESTAMP");$q->execute([$u['student_id'],$id,trim($_POST['note']??'')]);$notice='Request galmaa’eera.';}}
$q=$pdo->prepare('SELECT cr.*,o.name office_name FROM clearance_requests cr JOIN offices o ON o.id=cr.office_id WHERE cr.student_id=? ORDER BY o.id');$q->execute([$u['student_id']]);$rows=$q->fetchAll();$offices=$pdo->query('SELECT * FROM offices ORDER BY id')->fetchAll();$pageTitle='My Clearance';require __DIR__.'/includes/header.php';?>
<h1>My clearance</h1><?php if($notice):?><p class="success"><?=h($notice)?></p><?php endif;?>
<section class="panel"><h2>Submit / update request</h2><form method="post"><label>Office</label><select name="office_id"><?php foreach($offices as $o):?><option value="<?=$o['id']?>"><?=h($o['name'])?></option><?php endforeach;?></select><label>Note</label><input name="note" maxlength="500"><button>Submit</button></form></section>
<section class="panel"><h2>Status by office</h2><div class="tablewrap"><table><tr><th>Office</th><th>Status</th><th>Student note</th><th>Office note</th><th>Updated</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['office_name'])?></td><td><span class="status <?=strtolower($r['status'])?>"><?=h($r['status'])?></span></td><td><?=h($r['student_note'])?></td><td><?=h($r['office_note'])?></td><td><?=h($r['updated_at'])?></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>